Contract AirportSystem::createStaff(id:Integer,name:String,pswd:String,phone:String,role:Integer,bossid:Integer): Boolean {
          definition:
          newStaff:Staff = Staff.allInstance()->any(s | s.Id = id), boss:Staff = Staff.allInstance()->any(s | s.Id = bossid)

            precondition:
          newStaff.oclIsUndefined() = true and boss.oclIsUndefined() = false

            postcondition:
          let newStaff:Staff in newStaff.oclIsNew(), newStaff.Id = id, newStaff.Name = name, newStaff.Password = pswd, newStaff.Phone = phone, newStaff.Role = role, newStaff.Boss = boss, Staff.allInstance()->includes(newStaff)

        }

