Contract CoCoMESystem::receiveOrderedProduct(orderID:Integer): Boolean {
          definition:
          order:OrderProduct = OrderProduct.allInstance()->any(o | o.Id = orderID), items:Set(Item) = order.ContainedEntries->collect(e | e.Item)

            precondition:
          order.oclIsUndefined() = false and order.OrderStatus = OrderStatus::REQUESTED and items->forAll(i | i.StockNumber >= 0)

            postcondition:
          let newOrder:OrderProduct in newOrder.oclIsNew(), newOrder.Id = orderID, newOrder.OrderStatus = OrderStatus::RECEIVED, OrderProduct.allInstance()->includes(newOrder), items->forAll(i | i.StockNumber = i.StockNumber - i.OrderPrice)

        }

Contract LibraryManagementSystemSystem::cancelReservation(uid:String,barcode:String): Boolean {
          definition:
          user:User = User.allInstance()->any(u | u.UserID = uid), bookCopy:BookCopy = BookCopy.allInstance()->any(b | b.Barcode = barcode)

            precondition:
          user.oclIsUndefined() = false and bookCopy.oclIsUndefined() = false and bookCopy.IsReserved = true and user.LoanedBook->exists(l | l.LoanedCopy = bookCopy)

            postcondition:
          let reserve:Reserve in reserve.oclIsNew(), reserve.ReservedUser = user, reserve.ReservedCopy = bookCopy, reserve.IsReserveClosed = false, User.allInstance()->includes(user), BookCopy.allInstance()->includes(bookCopy)

        }

Contract SearchBook::searchBookByBarCode(barcode:String): Set(Book) {
          definition:
          bookCopies:Set(BookCopy) = BookCopy.allInstance()->select(bc | bc.Barcode = barcode)

            precondition:
          bookCopies->forAll(bc:BookCopy | bc.oclIsUndefined() = false) and bookCopies.size() > 0

            postcondition:
          let books:Set(Book) in books = bookCopies->collect(bc:BookCopy | bc.BookBelongs), books->forAll(b:Book | b.oclIsUndefined() = false)

        }

